3	namespace App\Providers\Filament;
4	
5	use BezhanSalleh\FilamentShield\FilamentShieldPlugin;
6	use Filament\Http\Middleware\Authenticate;
7	use Filament\Http\Middleware\AuthenticateSession;
8	use Filament\Http\Middleware\DisableBladeIconComponents;
9	use Filament\Http\Middleware\DispatchServingFilamentEvent;
10	use Filament\Pages\Dashboard;
11	use Filament\Panel;
12	use Filament\PanelProvider;
13	use Filament\Support\Colors\Color;
14	use Filament\Widgets\AccountWidget;
15	use Filament\Widgets\FilamentInfoWidget;
16	use Illuminate\Cookie\Middleware\AddQueuedCookiesToResponse;
17	use Illuminate\Cookie\Middleware\EncryptCookies;
18	use Illuminate\Foundation\Http\Middleware\PreventRequestForgery;
19	use Illuminate\Routing\Middleware\SubstituteBindings;
20	use Illuminate\Session\Middleware\StartSession;
21	use Illuminate\Support\Facades\Route;
22	use Illuminate\View\Middleware\ShareErrorsFromSession;
23	use Livewire\Livewire;
24	
25	class AdminPanelProvider extends PanelProvider
26	{
27	    public function boot(): void
28	    {
29	        /**
30	         * this fixes the issue with nginx server, where livewire.js is not found
31	         * (removing the dot forces nginx to follow the route and to not serve it as static file)
32	         * @see https://benjamincrozat.com/livewire-js-404-not-found
33	         * @see https://laracasts.com/discuss/channels/livewire/has-anyone-got-livewire-3-running-in-production-on-a-nginx-server
34	         */
35	        Livewire::setScriptRoute(function ($handle) {
36	            // @phpstan-ignore argument.type (su $handle)
37	            return Route::get('/livewire/livewirejs', $handle);
38	        });
39	    }
40	
41	    public function panel(Panel $panel): Panel
42	    {
43	        return $panel
44	            ->default()
45	            ->id('admin')
46	            ->path('admin')
47	            ->login()
48	            ->passwordReset()
49	            ->colors([
50	                'primary' => Color::Amber,
51	            ])
52	            ->viteTheme('resources/css/filament/admin/theme.css')
53	            ->discoverResources(in: app_path('Filament/Resources'), for: 'App\Filament\Resources')
54	            ->discoverPages(in: app_path('Filament/Pages'), for: 'App\Filament\Pages')
55	            ->pages([
56	                Dashboard::class,
57	            ])
58	            ->discoverWidgets(in: app_path('Filament/Widgets'), for: 'App\Filament\Widgets')
59	            ->widgets([
60	                AccountWidget::class,
61	                FilamentInfoWidget::class,
62	            ])
63	            ->middleware([
64	                EncryptCookies::class,
65	                AddQueuedCookiesToResponse::class,
66	                StartSession::class,
67	                AuthenticateSession::class,
68	                ShareErrorsFromSession::class,
69	                PreventRequestForgery::class,
70	                SubstituteBindings::class,
71	                DisableBladeIconComponents::class,
72	                DispatchServingFilamentEvent::class,
73	            ])
74	            ->plugins([
75	                FilamentShieldPlugin::make(),
76	            ])
77	            ->authMiddleware([
78	                Authenticate::class,
79	            ]);
80	    }
81	}
