53	            ]);
54	        }
55	
56	
57	        $panel->login(Login::class)
58	        ->id('admin')
59	        ->default()
60	        ->path('admin')
61	        ->viteTheme('vendor/atrioteam/filament-helper/resources/theme/theme.scss')
62	        ->brandName(config('app.name'))
63	        ->brandLogo(fn () => view('filament-helper::logo.admin-logo', [
64	            'logo' => asset('img/logo.svg'),
65	        ]))
66	        ->maxContentWidth(Width::Full)
67	        ->discoverResources(in: app_path('Filament/Resources'), for: 'App\\Filament\\Resources')
68	        ->discoverPages(in: app_path('Filament/Pages'), for: 'App\\Filament\\Pages')
69	        ->pages([
70	            \App\Filament\Pages\Dashboard::class,
71	        ])
72	        ->discoverWidgets(in: app_path('Filament/Widgets'), for: 'App\\Filament\\Widgets')
73	        ->widgets([
74	            AccountWidget::class,
75	            FilamentInfoWidget::class,
76	        ])
77	        ->middleware([
78	            EncryptCookies::class,
79	            AddQueuedCookiesToResponse::class,
80	            StartSession::class,
81	            AuthenticateSession::class,
82	            ShareErrorsFromSession::class,
83	            VerifyCsrfToken::class,
84	            SubstituteBindings::class,
85	            DisableBladeIconComponents::class,
86	            DispatchServingFilamentEvent::class,
87	        ])
88	        ->plugins([
89	            FilamentShieldPlugin::make(),
90	            MinimalTheme::make(),
91	        ])
92	        ->authMiddleware([
93	            Authenticate::class,
94	        ])
95	        // to be called after plugin registration, to overwrite colors set by MinimalTheme
96	        ->colors([
97	            'primary' => Color::hex('#04A9F5'),
98	        ])
99	        // custom avatar provider
100	        ->defaultAvatarProvider(AvatarsProvider::class)
101	        // load fonts from local filesystem
102	        ->font(
103	            'Inter',
104	            url: asset('fonts/filament-helper/fonts.css'),
105	            provider: LocalFontProvider::class,
106	        )
107	        ->globalSearch(false)
108	        ->unsavedChangesAlerts(app()->environment('production'));
109	    }
110	}
