3	namespace App\Providers\Filament;
4	
5	use App\Filament\Resources\AdminResource;
6	use App\Models\User;
7	use AtrioTeam\FilamentHelper\Jobs\OptimizeImage;
8	use AtrioTeam\FilamentHelper\PanelDefaults;
9	use BezhanSalleh\FilamentShield\Facades\FilamentShield;
10	use Filament\Panel;
11	use Filament\PanelProvider;
12	use Illuminate\Support\Facades\Event;
13	use Illuminate\Support\Facades\Storage;
14	use Spatie\MediaLibrary\ResponsiveImages\Events\ResponsiveImagesGeneratedEvent;
15	
16	/**
17	 * Admin panel provider for the site.
18	 * Uses the default configuration from the filament-helper package.
19	 */
20	class AdminPanelProvider extends PanelProvider
21	{
22	    public function panel(Panel $panel): Panel
23	    {
24	
25	        PanelDefaults::make($panel);
26	
27	        // add further customizations here...
28	
29	        /**
30	         * AdminResource usa User come modello, ma i permessi Shield devono
31	         * usare 'Admin' come entità (non 'User') per distinguerli.
32	         */
33	        FilamentShield::buildPermissionKeyUsing(
34	            function (string $entity, string $affix, string $subject, string $case, string $separator): string {
35	                if ($entity === AdminResource::class) {
36	                    $subject = 'Admin';
37	                }
38	
39	                return FilamentShield::defaultPermissionKeyBuilder(
40	                    affix: $affix,
41	                    separator: $separator,
42	                    subject: $subject,
43	                    case: $case,
44	                );
45	            }
46	        );
47	
48	        if (config('filament-helper.tinify.enabled')) {
49	            $this->registerImageOptimizationJob();
50	        }
51	
52	        return $panel;
53	
54	    }
55	
56	    protected function registerImageOptimizationJob(): void
57	    {
58	        Event::listen(
59	            ResponsiveImagesGeneratedEvent::class,
60	            function (ResponsiveImagesGeneratedEvent $event) {
61	
62	                // loop thorught responsive images and build path for each of them, then dispatch the job to optimize the image
63	                foreach ($event->media->responsive_images as $conversionName) {
64	
65	                    foreach ($conversionName['urls'] as $relativePath) {
66	                        $imagePath = Storage::disk($event->media->disk)->path(implode('/', [
67	                            $event->media->id,
68	                            'responsive-images',
69	                            $relativePath
70	                        ]));
71	
72	                        OptimizeImage::dispatch($imagePath);
73	
74	                    }
75	                }
76	            }
77	        );
78	
79	    }
80	
81	}
