import { defineConfig } from 'vite';
import laravel from 'laravel-vite-plugin';
import path from 'path'
import sass from 'vite-plugin-sass';
import tailwindcss from "@tailwindcss/vite";

var config = {
    // https://github.com/uikit/uikit/issues/3399
    resolve: {
        alias: {
            'uikit-util': path.resolve(__dirname, './node_modules/uikit/src/js/util/index.js'),
        },
    },
    server: { 
        hmr: {
            host: 'localhost',
            clientPort: process.env.VITE_CLIENT_PORT,
        },
        watch: {
            ignored : ['**/lang/vendor/lintilla/**', '**/lang/**'],
        }
    }, 
    plugins: [
        laravel({
            input: [

                /**
                 * core js
                 */
                'resources/js/boot.js',
                'resources/js/vendor.js',
                'resources/js/app.js',

                /**
                 * core css
                 */
                'resources/sass/boot.scss',
                'resources/sass/main.scss',
                'resources/sass/pages.scss',

                /**
                 * filament theme e css custom per filament
                 * attivare se si usa filament!
                 */
                'vendor/atrioteam/filament-helper/resources/theme/theme.scss',
                // 'resources/sass/filament-custom.scss'


            ],
            refresh: true,
        }),
        sass,
        tailwindcss(),
    ],
    css: {
        devSourcemap: true,
        sourcemap: true,
        preprocessorOptions: {
            scss: {
                silenceDeprecations: ['import', 'legacy-js-api'],
            },
        },
    },
    build: {
        sourcemap: true,
    },
};

export default defineConfig(({command, mode, ssrBuild}) => {

    // allow using assets loaded in public folder during development
    if (command === 'serve') {
        config.publicDir = 'public';
        config.build = {
            assetsDir: '',
            copyPublicDir: false,
            emptyOutDir: true,
        };
    }

    return config;
}); 




