// default filament theme
@import 'tailwindcss' source(none);
@import '/vendor/filament/filament/resources/css/index.css';


// minimal theme
@import '/vendor/filament-themes/minimal/index.css';


@source '../../../../../app/Filament/Resources/**/*.php';
@source '../../../../../app/Filament/Admin/**/*.php';
@source '../../../../../resources/views/filament/**/*.blade.php';
@source '../../../../../resources/views/filament/admin/**/*.blade.php';
@source '../../../../../vendor/filament/**/*.blade.php';
@source '../../../../../vendor/jaocero/radio-deck/resources/views/**/*.blade.php';
@source '../../../../../vendor/atrioteam/filament-helper/resources/views/**/*.blade.php';
@source '../../../../../resources/views/vendor/**/*.blade.php';



/**
 * =================================================================
 * General layout
 * =================================================================
 */
 .fi-topbar,
 .fi-sidebar-header
 {
    @apply bg-black text-white;

    .fi-logo span {
        @apply text-white;
    }
}

.fi-sidebar-header {
    @apply shadow-none!;
    border: 0;
    height: 4rem; 
}

.fi-sidebar-group .fi-sidebar-group-label {
    @apply font-medium uppercase text-black dark:text-gray-400 tracking-widest;
}

.fi-sidebar-item {

    &-icon {display: none}
}

/**
 * page header
 */
.fi-breadcrumbs-item-label {
    @apply text-black dark:text-gray-400 font-normal tracking-wide;
}
.fi-header-heading {
    @apply font-medium;
}


// overwrite sticky header font size, back to filament default
.fi-main.is-sticky .fi-header .fi-header-heading {
    @apply text-2xl  sm:text-3xl!;
}

.is-sticky.sticky-theme-default .fi-header:before {
    @apply border-black;
}

/**
 * table
 */
 // hide default ordering button, if not inside a modal (e.g. relation manager)
 // hide default ordering button, if not inside a modal (e.g. relation manager)
.fi-ta-header-toolbar:not(.fi-modal-content *):not(.fi-resource-relation-manager *)
{
    button[wire\:click="toggleTableReordering"] {
        display: none;
    }
}


.fi-ta-table {
    .fi-ta-header-cell-label {
        @apply font-medium uppercase tracking-wider text-black dark:text-gray-400 text-xs;
    }

}

/**
 * =================================================================
 * END Layout
 * =================================================================
 */



/**
 * =================================================================
 * Components
 * =================================================================
 */
.fi-sc-section {
    @apply mb-0 mt-3 pt-0 pb-9;
}

.fi-sc-section:not(.no-border) {
    @apply  border-b border-gray-300 dark:border-white;
}
.fi-sc-section.no-border {
    @apply border-0;
}

.fi-section-header-heading {
    @apply text-xl pt-0 pb-4 font-semibold;

    &::before {
        content: '#'
    }
}

.fi-sc-actions {
    @apply mb-0 mt-2 pt-0 border-gray-300 dark:border-white;
}

// fix per colori bottoni, per renderli simili a v3.
// credits https://github.com/filamentphp/filament/discussions/17517#discussioncomment-15442863
.fi-btn {
    &:not(.fi-outlined) {
        &.fi-color {
            --bg: var(--color-600) !important;
            --text: white !important;
            --hover-bg: var(--color-500) !important;
            --hover-text: white !important;
        }
    }
}

// hide default "reorder" trigger button
// .reorder-trigger-before is rendered via a render hook
// .reorder-trigger-before + span {display: none;}


/* .fi-btn {
    // @apply py-4;
} */
/**
 * =================================================================
 * END components
 * =================================================================
 */


/**
 * =================================================================
 * Login page
 * =================================================================
 */

 // revert the padding and border removed in the minimal theme
 .fi-simple-layout:has(.afh-login-wrapper) {
    background: rgb(250, 250, 250);
    @apply dark:bg-gray-700;
}

.afh-login-wrapper {

    @apply p-12 shadow-xl rounded-xl bg-white dark:bg-gray-800;

    .fi-logo {display: none;}


    .fi-simple-header-heading {
