import { defineConfig } from 'vite';
import laravel from 'laravel-vite-plugin';
import { bunny } from 'laravel-vite-plugin/fonts';
import sass from 'vite-plugin-sass';
import tailwindcss from '@tailwindcss/vite';

export default defineConfig({
    plugins: [
        laravel({
            // Entrypoint separati per le due audience della stessa app
            input: [
                'resources/css/app.css',
                'resources/js/app.js',
                // Tema del pannello admin: il .scss di atrioteam/filament-helper,
                // registrato via viteTheme() in PanelDefaults. Compilato da sass-embedded.
                'vendor/atrioteam/filament-helper/resources/theme/theme.scss',
            ],
            refresh: true,
            fonts: [
                bunny('Instrument Sans', {
                    weights: [400, 500, 600],
                }),
            ],
        }),
        sass,
        tailwindcss(),
    ],
    css: {
        preprocessorOptions: {
            scss: {
                silenceDeprecations: ['import', 'legacy-js-api'],
            },
        },
    },
    server: {
        // il client gira sull'host, il server dentro il container node:
        // la porta pubblicata è quella mappata nel docker-compose.
        hmr: {
            host: 'localhost',
            clientPort: process.env.VITE_CLIENT_PORT,
        },
        watch: {
            ignored: ['**/storage/framework/views/**'],
        },
    },
});

